from datetime import datetime, timezone

_DEFAULT = (5, 8.0, 30.0)  # attempts, backoff cap, max Retry-After
_PROFILES = {
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
    "catalog": (6, 8.0, 30.0),
    "auth": (6, 6.0, 20.0),
    "ledger": (8, 3.0, 60.0),
}
_MONTHS = {m: i + 1 for i, m in enumerate(
    "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split())}
_DATE_RE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\\d{2}) ([A-Z][a-z]{2}) (\\d{4}) "
    r"(\\d{2}):(\\d{2}):(\\d{2}) GMT")


def _header(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Seconds, or None when absent/malformed."""
    if value is None:
        return None
    value = value.strip() if isinstance(value, str) else value
    if not isinstance(value, str):
        return None
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _DATE_RE.fullmatch(value)
    if not m or m.group(3) not in _MONTHS:
        return None
    try:
        dt = datetime(int(m.group(4)), _MONTHS[m.group(3)], int(m.group(2)),
                      int(m.group(5)), int(m.group(6)), int(m.group(7)),
                      tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (dt - now).total_seconds())
''',1)
